sys_variable_value.value:
(function execute(inputs, outputs) {
    var students = []

        var enrollmentGR = new GlideRecord("x_1131775_traini_0_enrollment");
        enrollmentGR.addQuery('training_schedule', inputs.enrollments.getValue('training_schedule'));
        enrollmentGR.addQuery('number', inputs.enrollments.getValue("number"));
        enrollmentGR.query();

        while (enrollmentGR.next()) {
            students = enrollmentGR.getValue('opened_by');
        }
    outputs.students_list = students;
})(inputs, outputs);

